      "content": "{\n  \"name\": \"dsh-polymarket-proxy\",\n  \"version\": \"1.1.0\",\n  \"description\": \"Polymarket Proxy for DeepSeek Harness: a local portfolio, cash and deposit-address panel with an auto-refreshing market radar, live betting and instant position closes — for when the official Polymarket site blocks deposits or trading. Follows the Harness language (English unless the interface is Chinese).\",\n  \"license\": \"MIT\",\n  \"author\": \"dennisyang1986\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/dennisyang1986/polymarket-proxy.git\"\n  },\n  \"homepage\": \"https://github.com/dennisyang1986/polymarket-proxy#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/dennisyang1986/polymarket-proxy/issues\"\n  },\n  \"engines\": {\n    \"node\": \">=24\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"polymarket\",\n    \"prediction-market\",\n    \"trading\",\n    \"portfolio\"\n  ],\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./client.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./icon\": \"./icon.svg\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"bridge.js\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"locale/*.json\",\n    \"keywords.default.txt\",\n    \"icon.svg\",\n    \"assets\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"screenshots.json\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": []\n    }\n  },\n  \"dependencies\": {\n    \"@polymarket/client\": \"^0.18.0\",\n    \"qrcode-generator\": \"^1.4.4\",\n    \"viem\": \"^2.57.19\"\n  }\n}\n"
